#!/usr/bin/env python3
"""
Nexus IDE Connectors - Generate config/env for all AI coding agents.
Run: python -m ide_connector.generate_all
"""
import os, sys, json
from pathlib import Path

NEXUS_CONFIG = """
# Generated by NEXUS IDE Connector
# Source: nexus.yaml

# ── Nexus Proxy ─────────────────────────────────────────────────────────────
export NEXUS_API_BASE="http://localhost:8000/v1"
export NEXUS_API_KEY="{nexus_api_key}"
export NEXUS_PROXY_PORT=8000

# ── Ollama Cloud ─────────────────────────────────────────────────────────────
export OLLAMA_CLOUD_API_KEY="{ollama_api_key}"

# ── NVIDIA NIM ───────────────────────────────────────────────────────────────
export NVIDIA_NIM_API_KEY="{nvidia_api_key}"

# ── Claude Code ─────────────────────────────────────────────────────────────
export ANTHROPIC_BASE_URL="http://localhost:8000/v1"
export ANTHROPIC_API_KEY="nexus-{nexus_api_key}"
export CLAUDE_CODE_USE_MCP_SERVER="nexus"

# ── Aider ────────────────────────────────────────────────────────────────────
export OPENAI_API_BASE="http://localhost:8000/v1"
export OPENAI_API_KEY="{nexus_api_key}"

# ── OpenCode ─────────────────────────────────────────────────────────────────
# OpenCode reads OPENAI_API_BASE from config
"""

CLAUDE_CODE_CLAUDE_JSON = """
{
  "model": "anthropic/claude-sonnet-4-20250514",
  "anthropic": true,
  "tools": {
    "mcpServers": {
      "nexus": {
        "command": "python3",
        "args": ["-m", "server.unified", "--port", "9090"]
      }
    }
  }
}
"""

IDE_SCRIPTS = {
    "claude_code": {
        "description": "Claude Code MCP connection to NEXUS",
        "env_file": ".env.nexus",
        "claude_json": ".claude.json",
    },
    "aider": {
        "description": "Aider model routing via NEXUS proxy",
        "env_file": ".env.aider",
        "model_list": "aider_models.yml",
    },
    "opencode": {
        "description": "OpenCode OpenAI API base config",
        "env_file": ".env.opencode",
    },
    "codex": {
        "description": "Codex via viacline/claude.nvim",
        "env_file": ".env.codex",
    }
}


def generate_env_file(path: str, api_keys: dict):
    content = NEXUS_CONFIG.format(
        nexus_api_key=api_keys.get("nexus_api_key", "changeme"),
        ollama_api_key=api_keys.get("ollama_api_key", ""),
        nvidia_api_key=api_keys.get("nvidia_api_key", ""),
    )
    with open(path, "w") as f:
        f.write(content)
    print(f"Generated: {path}")
    print(f"  -> Set API keys: OLLAMA_CLOUD_API_KEY, NVIDIA_NIM_API_KEY, NEXUS_API_KEY")


def generate_claude_code_config(path: str):
    content = json.dumps(json.loads(CLAUDE_CODE_CLAUDE_JSON), indent=2)
    with open(path, "w") as f:
        f.write(content)
    print(f"Generated: {path}")


def generate_aider_model_list(path: str):
    content = """# Aider model routing - generated by NEXUS
# Place at ~/.config/aider.model_list.yml or ./aider_models.yml

models:
  - name: ollama/deepseek-v4-flash
    api_base: http://localhost:8000/v1
    model_type: chat

  - name: ollama/kimi-k2.6
    api_base: http://localhost:8000/v1
    model_type: chat

  - name: ollama/glm-5.1
    api_base: http://localhost:8000/v1
    model_type: chat

  - name: nvidia/meta-llama-3.1-70b
    api_base: http://localhost:8000/v1
    model_type: chat
"""
    with open(path, "w") as f:
        f.write(content)
    print(f"Generated: {path}")


def generate_shell_aliases(path: str):
    content = """# NEXUS Shell Aliases - add to ~/.bashrc or ~/.zshrc

# NEXUS control
alias nexus-start='cd ~/nexus && python -m core.server --config nexus.yaml &'
alias nexus-stop='kill $(lsof -t -i:8000) 2>/dev/null; echo "Nexus stopped"'
alias nexus-status='curl -s http://localhost:8000/health | python -m json.tool'

# IDE connections
alias nexus-env='source ~/.env.nexus'
alias nexus-config='nano ~/nexus/nexus.yaml'

# Benchmark
alias nexus-bench='python ~/nexus/scripts/run_benchmark.py'
"""
    with open(path, "w") as f:
        f.write(content)
    print(f"Generated: {path}")


def main():
    base = Path.home() / "nexus" / "ide_connector"
    base.mkdir(parents=True, exist_ok=True)

    api_keys = {
        "nexus_api_key": os.environ.get("NEXUS_API_KEY", "nexus-secret-key"),
        "ollama_api_key": os.environ.get("OLLAMA_CLOUD_API_KEY", ""),
        "nvidia_api_key": os.environ.get("NVIDIA_NIM_API_KEY", ""),
    }

    # Generate all configs
    generate_env_file(base / ".env.nexus", api_keys)
    generate_aider_model_list(base / "aider_models.yml")
    generate_shell_aliases(base / "nexus-aliases.sh")

    print("\n=== NEXUS IDE Connector Setup Complete ===")
    print("Files generated:")
    print("  ~/.env.nexus              - Source this in shell: source ~/.env.nexus")
    print("  ~/nexus/ide_connector/aider_models.yml - Aider model routing list")
    print("  ~/nexus/ide_connector/nexus-aliases.sh - Shell aliases")
    print("\nTo activate:")
    print("  1. source ~/.env.nexus")
    print("  2. python -m core.server --config ~/nexus/nexus.yaml &")
    print("  3. nexus-status  # verify running")


if __name__ == "__main__":
    main()